package com.company.platform.order.infrastructure;
import com.company.platform.order.application.CommerceCheckoutPort;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Component;import org.springframework.web.client.RestClient;import java.util.*;import java.math.BigDecimal;
@Component public class HttpCommerceCheckoutAdapter implements CommerceCheckoutPort{private final RestClient client;public HttpCommerceCheckoutAdapter(@Value("${commerce.base-url:http://localhost:8085}")String base){client=RestClient.builder().baseUrl(base).build();}
 @SuppressWarnings("unchecked") public ShoppingCart loadCart(UUID t,UUID id){Map<String,Object> m=client.get().uri("/commerce/carts/{id}",id).header("X-Tenant-Id",t.toString()).retrieve().body(Map.class);if(m==null)return null;List<CartLine> lines=new ArrayList<>();for(Map<String,Object> i:(List<Map<String,Object>>)m.getOrDefault("items",List.of())){Map<String,Object> money=(Map<String,Object>)i.get("unitPrice");lines.add(new CartLine(UUID.fromString((String)i.get("sellableProductId")),null,null,((Number)i.get("quantity")).intValue(),new BigDecimal(money.get("amount").toString()),(String)money.get("currency")));}return new ShoppingCart(UUID.fromString((String)m.get("id")),UUID.fromString((String)m.get("tenantId")),UUID.fromString((String)m.get("customerId")),UUID.fromString((String)m.get("storeId")),(String)m.get("status"),lines);}
 @SuppressWarnings("unchecked") public CommercialPrice activePrice(UUID t,UUID id){try{Map<String,Object> m=client.get().uri("/commerce/products/{id}/current-price",id).header("X-Tenant-Id",t.toString()).retrieve().body(Map.class);Map<String,Object> money=(Map<String,Object>)m.get("money");return new CommercialPrice(id,null,null,new BigDecimal(money.get("amount").toString()),(String)money.get("currency"),"ACTIVE".equals(m.get("status")),true);}catch(Exception e){return null;}}
 public void completeCart(UUID t,UUID id){client.post().uri("/commerce/carts/{id}/complete",id).header("X-Tenant-Id",t.toString()).retrieve().toBodilessEntity();}}
